<template>
  <div v-if="tour" class="page">
    <NuxtLink :to="`/tours/${tour.id}`" class="back">← Вернуться к предложению</NuxtLink>
    <div class="layout">
      <main><span class="kicker">Бронирование в Trove</span><h1>Оформим поездку 🐱</h1><div class="secure-line"><ShieldCheck :size="16" /><span>Защищённое оформление · цена проверяется ещё раз перед оплатой</span></div>
      <p class="lead">Сначала данные путешественников. Оплата пока работает как отдельный этап — данные карты Trove не хранит.</p>
        <section class="card"><h2>Контакты</h2><div class="fields"><label>Email<input v-model="contact.email" type="email" autocomplete="email"></label><label>Телефон<input v-model="contact.phone" type="tel" autocomplete="tel"></label></div></section>
        <section class="card"><h2>Адрес плательщика</h2><div class="fields"><label>Страна<input v-model="contact.address.country" autocomplete="country"></label><label>Город<input v-model="contact.address.city" autocomplete="address-level2"></label><label>Адрес<input v-model="contact.address.address" autocomplete="street-address"></label><label>Индекс<input v-model="contact.address.zip" autocomplete="postal-code"></label></div></section><section class="card"><h2>Скидка и промокод</h2><div class="promo-row"><input v-model="promoCode" placeholder="Введите промокод" @keyup.enter="checkPromo"><button type="button" @click="checkPromo" :disabled="promoLoading">{{ promoLoading ? "Проверяем…" : "Применить" }}</button></div><p v-if="promoMessage" :class="{promoError: !promoValid, promoSuccess: promoValid}" class="promo-message">{{ promoMessage }}</p><div v-if="loyaltyDiscount > 0 && !promoValid" class="loyalty-note">🐱 У вас {{ loyaltyDiscount }}% персональной скидки как постоянного клиента.</div></section><section class="card"><div class="section-head"><h2>Путешественники</h2><button type="button" @click="addPassenger">+ Добавить</button></div><div v-for="(passenger,index) in passengers" :key="index" class="passenger"><strong>Путешественник {{index+1}}</strong><div class="fields"><label>Имя<input v-model="passenger.firstName" autocomplete="given-name"></label><label>Фамилия<input v-model="passenger.lastName" autocomplete="family-name"></label><label>Дата рождения<input v-model="passenger.birthDate" type="date"></label></div><button v-if="passengers.length>1" class="remove" type="button" @click="passengers.splice(index,1)">Удалить</button></div></section>
        <label class="consent"><input v-model="termsAccepted" type="checkbox"> <span>Я принимаю <NuxtLink to="/legal/terms" target="_blank">условия использования</NuxtLink> и <NuxtLink to="/legal/privacy" target="_blank">политику конфиденциальности</NuxtLink>.</span></label><div v-if="error" class="error">{{ error }}</div><button class="primary" :disabled="loading" @click="submit">{{loading?'Проверяем цену и оформляем оплату…':'Создать бронирование →'}}</button>
      </main>
      <aside class="summary"><img :src="tour.image" :alt="tour.title"><span class="kicker">Ваш выбор</span><h2>{{tour.title}}</h2><p>{{tour.hotel}}</p><div class="line"><span>{{tour.destination}}</span><strong>{{tour.duration}} ночей</strong></div><div class="line"><span>Цена</span><strong>{{formatPrice(displayPrice,tour.currency)}}</strong></div><div v-if="discount > 0" class="line discount"><span>Скидка</span><strong>−{{formatPrice(discount,tour.currency)}}</strong></div><small>Цена будет повторно проверена перед созданием заказа.</small></aside>
    </div>
  </div>
</template>
<script setup lang="ts">
import { ShieldCheck } from '@lucide/vue'
import { formatPrice } from '@entities/tours/model/tour'
import type { Tour } from '~/types/tours'
const route=useRoute(); const analytics=useAnalytics(); const auth=useAuth(); const {getDetail}=useTours(); const bookings=useBookings(); const loyalty=useLoyalty(); const tour=ref<Tour|null>(null); const loading=ref(false); const error=ref(''); const promoCode=ref(''); const promoLoading=ref(false); const promoValid=ref(false); const promoMessage=ref(''); const promoDiscount=ref(0); const loyaltyDiscount=ref(0); const contact=reactive({email:'',phone:'',address:{country:'RU',city:'',address:'',zip:''}}); const passengers=ref([{firstName:'',lastName:'',birthDate:''}]); const termsAccepted=ref(false)
const discount=computed(()=>promoValid.value?promoDiscount.value:(tour.value?Math.round(tour.value.price*loyaltyDiscount.value/100):0)); const displayPrice=computed(()=>tour.value?Math.max(1,tour.value.price-discount.value):0);
const checkPromo=async()=>{if(!tour.value||!promoCode.value.trim())return;promoLoading.value=true;promoMessage.value='';promoValid.value=false;try{const q=await loyalty.validate(promoCode.value,tour.value.price,tour.value.destination);promoValid.value=q.valid;promoDiscount.value=q.discount;promoMessage.value=q.valid?`Промокод применён: −${formatPrice(q.discount,tour.value.currency)}`:(q.reason||'Промокод недействителен')}catch(e){promoMessage.value=e instanceof Error?e.message:'Промокод недействителен'}finally{promoLoading.value=false}};
const addPassenger=()=>{if(passengers.value.length<9)passengers.value.push({firstName:'',lastName:'',birthDate:''})}
onMounted(async()=>{await auth.load();if(!auth.user.value){await navigateTo({path:'/auth/login',query:{redirect:`/booking/${route.params.id}`}});return};contact.email=auth.user.value.email||'';contact.phone=auth.user.value.phone||'';await loyalty.load().catch(()=>undefined); loyaltyDiscount.value=loyalty.profile.value?.personalDiscountPercent ?? 0; const d=await getDetail(String(route.params.id));if(!d){await navigateTo('/tours');return};tour.value=d.item})
const submit=async()=>{if(!tour.value)return;error.value='';if(!termsAccepted.value){error.value='Подтвердите согласие с условиями использования и политикой конфиденциальности.';return};if(!contact.email||!contact.phone||!contact.address.country||!contact.address.city||!contact.address.address||passengers.value.some(p=>!p.firstName.trim()||!p.lastName.trim())){error.value='Заполните email, имя и фамилию каждого путешественника.';return};void analytics.track('checkout_started',{offerId:tour.value.id});loading.value=true;try{const d=await getDetail(tour.value.id);if(!d)throw new Error('Предложение не найдено');const idempotencyKey=crypto.randomUUID();const preview=await bookings.preview({offerId:tour.value.id,providerId:d.provider.id,passengers:passengers.value,contact,promoCode:promoValid.value?promoCode.value.trim():undefined,idempotencyKey,consent:{termsAccepted:true,termsVersion:'2026-09-21',privacyVersion:'2026-09-21'}});const intent=await bookings.createPaymentIntent(preview.id);if (intent.checkoutUrl) { window.location.assign(intent.checkoutUrl); return }
    await navigateTo({path:`/payment/mock/${intent.id}`,query:{bookingId:preview.id,previewToken:preview.previewToken}})}catch(e){error.value=e instanceof Error?e.message:'Не удалось создать бронирование'}finally{loading.value=false}}
</script>
<style scoped lang="scss">
