focus{border-color:var(--brand);box-shadow:0 0 0 3px rgba(242,100,74,.11)}.section-head{display:flex;justify-content:space-between;align-items:center}.section-head button{min-height:36px;padding:0 11px;border:1px solid var(--line);border-radius:9px;background:var(--paper);color:var(--ink);font-size:10px;font-weight:800;cursor:pointer}.passenger{position:relative;margin-top:18px;padding-top:18px;border-top:1px solid var(--line)}.passenger strong{display:block;margin-bottom:11px;font-size:12px}.remove{margin-top:10px;border:0;background:none;color:var(--danger);font-size:10px;cursor:pointer}.promo-row{display:flex;gap:8px}.promo-row input{flex:1}.promo-row button{min-width:105px;border:0;border-radius:10px;background:var(--ink);color:#fff;font-size:11px;font-weight:800;cursor:pointer}.promo-message{font-size:11px!important;margin:9px 0 0}.promoSuccess{color:var(--green)!important}.promoError{color:var(--danger)!important}.loyalty-note{padding:11px;border-radius:10px;background:var(--surface);color:var(--muted);font-size:11px;margin-top:9px}.discount strong{color:var(--brand-dark)}.primary{width:100%;min-height:54px;margin-top:18px;border:0;border-radius:12px;background:var(--brand);color:#fff;font-weight:800;cursor:pointer;transition:.2s}.primary:hover{background:var(--brand-dark);transform:translateY(-1px);box-shadow:var(--shadow-md)}.primary:disabled{opacity:.55;cursor:wait}.consent{display:flex;align-items:flex-start;gap:8px;margin-top:16px;color:var(--muted);font-size:11px;line-height:1.5}.consent input{width:auto;margin:3px 0}.consent a{color:var(--ink)!important;text-decoration:underline}.error{margin-top:14px;padding:12px;border:1px solid #f0d1cb;border-radius:10px;background:#fff6f4;color:var(--danger);font-size:11px}.summary{margin-top:0;align-self:start;position:sticky;top:92px;overflow:hidden}.summary img{display:block;width:calc(100% + 48px);height:220px;object-fit:cover;margin:-24px -24px 20px}.summary p{color:var(--muted);font-size:12px}.line{display:flex;justify-content:space-between;gap:12px;padding:13px 0;border-top:1px solid var(--line);font-size:12px}.summary small{display:block;margin-top:10px;color:var(--muted);line-height:1.55;font-size:10px}.summary:after{content:'Цена будет повторно проверена перед созданием заказа';display:block;margin:16px -24px -24px;padding:13px 24px;background:var(--surface);color:var(--muted);font-size:10px;line-height:1.45}
@media(max-width:800px){.checkout-top{display:block}.steps{margin-top:16px;justify-content:space-between}.steps i{flex:1}.steps b{display:none}.layout{grid-template-columns:1fr}.summary{position:static;order:-1}.fields{grid-template-columns:1fr}h1{font-size:40px}.page{width:calc(100% - 32px)}}@media(max-width:520px){.promo-row{display:block}.promo-row button{width:100%;margin-top:8px}.steps i{width:18px}.card{padding:20px}.summary{padding:20px}.summary img{width:calc(100% + 40px);margin:-20px -20px 18px}}
</style>